import{_ as i,l,o as e,c as n,v as t,p as d,x as o,d as s,i as A,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"自动微分的正向与反向模式","description":"","frontmatter":{"title":"自动微分的正向与反向模式","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/autograd-two-modes.md","filePath":"llm/autograd-two-modes.md","lastUpdated":1789023840000}'),p={name:"llm/autograd-two-modes.md"};function E(_,a,h,m,u,D){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="自动微分的正向与反向模式" tabindex="-1">自动微分的正向与反向模式 <a class="header-anchor" href="#自动微分的正向与反向模式" aria-label="Permalink to &quot;自动微分的正向与反向模式&quot;">​</a></h1><div class="epigraph"><p>同一条链式法则，从输入往输出推是正向模式，从输出往输入推是反向模式；谁便宜，取决于自变量多还是因变量多。</p><footer>—— 据 Griewank &amp; Walther, Evaluating Derivatives；Baydin et al., Automatic Differentiation in Machine Learning, JMLR 2018 整理</footer></div><p><a href="/llm/backprop-layerwise">反向传播一行一层</a>默认从损失往参数走。本课不重写线性层的两次 GEMM。缺口是：自动微分还有另一种扫法——正向模式：每个中间量携带对某个输入的导数，随前向一起走。训练几乎总用反向，因为 \\(L\\) 是标量、\\(\\theta\\) 是百万到千亿维。正向模式在「少数输入、许多输出」时才更便宜。本课把两种复杂度钉住，避免把 backprop 当成 AD 的唯一定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计算图有 \\(n\\) 个独立输入、\\(m\\) 个输出。要全部一阶导数，即 \\(m\\times n\\) 的 Jacobian。正向模式选一个输入方向 \\(v\\)，一次扫图得到 \\(Jv\\)（Jacobian-vector）；要满 Jacobian，约需 \\(n\\) 次。反向模式选一个输出余向量 \\(u\\)，一次扫图得到 \\(u^\\top J\\)（vector-Jacobian）；要满 Jacobian，约需 \\(m\\) 次。缺口不是新的局部导数，而是这次计数：深度学习训练 \\(m=1\\)、\\(n\\) 极大，故反向一次就够；若问「每个输出对某一个输入」的敏感度，\\(n=1\\) 则正向一次就够。</p><p>框架里的 autograd 默认反向。Jacobian-vector 接口（有的叫 forward-over-reverse）用于二阶、用于梯度惩罚，那是后话。本课只要求能回答：为什么训练不跑正向 AD。</p><h3 id="正向模式不是「再做一次前向传播」" tabindex="-1">正向模式不是「再做一次前向传播」 <a class="header-anchor" href="#正向模式不是「再做一次前向传播」" aria-label="Permalink to &quot;正向模式不是「再做一次前向传播」&quot;">​</a></h3><p>前向传播算的是值。正向 AD 算的是值与切空间里的种子一起走：每个张量多带一个与自身同形的切向量。开销大约是常数倍的前向，不是「免费」。反向 AD 则要保存中间值，内存与图深度（或与检查点策略）相关。把正向 AD 理解成「不占内存的反向」，形状和次数都错：它省的是反向那次扫，不省对每个输入各扫一次的次数。</p><p><span class="marginnote">标量损失对参数的梯度是 \\(1\\times n\\) 的行。反向一次得到整行。正向要对每个参数种子跑一次，才能填满这一行。这就是训练不用正向模式的全部理由。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记图为复合 \\(f=f_k\\circ\\cdots\\circ f_1\\)。正向 AD：选 \\(v\\)，令 \\(\\dot x_0=v\\)，递推 \\(\\dot x_{i}=J_{f_i}\\dot x_{i-1}\\)，最后得到 \\(J_f v\\)。反向 AD：选 \\(u\\)，令 \\(\\bar x_k=u\\)，递推 \\(\\bar x_{i-1}=J_{f_i}^\\top\\bar x_i\\)，最后得到 \\(J_f^\\top u\\)。实现上，正向 AD 可与数值前向融合；反向 AD 要先完整前向再逆序。混合模式对中间层切分，用于极深图的检查点，本课只点名，不展开。</p>',11)),(e(),d(c,null,{default:o(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E8%AE%B8%E5%A4%9A%E5%8F%82%E6%95%B0%22%5D%20--%3E%20FWD%5B%22%E6%AD%A3%E5%90%91%E6%A8%A1%E5%BC%8F%20J%20%E4%B9%98%20v%22%5D%0A%20%20FWD%20--%3E%20OUTS%5B%22%E8%AE%B8%E5%A4%9A%E8%BE%93%E5%87%BA%E6%96%B9%E5%90%91%22%5D%0A%20%20LOSS%5B%22%E4%B8%80%E4%B8%AA%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20REV%5B%22%E5%8F%8D%E5%90%91%E6%A8%A1%E5%BC%8F%20u%20%E8%BD%AC%E7%BD%AE%E4%B9%98%20J%22%5D%0A%20%20REV%20--%3E%20GRADS%5B%22%E5%AF%B9%E6%89%80%E6%9C%89%E5%8F%82%E6%95%B0%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>复杂度差来自矩阵乘法结合律：\\((AB)v\\) 与 \\(u^\\top(AB)\\) 的结合顺序不同，中间维被收缩的次数就不同。层很宽时，物化完整 Jacobian 不可能；两种模式都只传播向量。反向模式还要面对内存：残差块可以把反向路径变短，检查点则用重计算换存储。这些是系统课的主题；机制上只需记住，反向不是计算上无条件更优，只是对「标量损失 + 大量参数」更优。</p><p>数值梯度检验常用正向有限差分对单个参数，那是 \\(O(n)\\) 次前向，只能抽样若干坐标。它检验的是局部规则写得对不对，不能替代 AD。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导 Hessian-vector 的两次反向。下一课<a href="/llm/vanish-explode-grad">梯度消失与爆炸</a>问的是反向路径上局部增益的连乘，不是 AD 模式选错。后课默认：训练用反向 AD；说到 Jacobian-vector，才考虑正向或正向嵌反向。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正向 AD 一次得 \\(Jv\\)，次数随输入维；反向 AD 一次得 \\(u^\\top J\\)，次数随输出维。</li><li>训练 \\(m=1\\)，故反向一次给出全部参数梯度。</li><li>正向 AD 不是免费前向，每个张量携带切向量。</li><li>反向 AD 的代价在内存与检查点，不在「算不出梯度」。</li><li>出处：Griewank &amp; Walther；Baydin et al., JMLR 2018。</li></ul>',7))])}const b=i(p,[["render",E]]);export{B as __pageData,b as default};
